def test__resolve_dim_sizes():
    sol_mock = unittest.mock.MagicMock(spec=Solution)
    sol_mock._resolve_dim_sizes.return_value = {}

    result = sol_mock._resolve_dim_sizes({'a', 'b'}, {'a': 10}, 20)
    assert result == {}, "Expected no resolved size dictionary"

